Here is the commit message:
vfio/mdev: Fix reference count leak in
 add_mdev_supported_type

kobject_init_and_add() takes reference even when it fails.
If this function returns an error, kobject_put() must be called to
properly clean up the memory associated with the object. Thus,
replace kfree() by kobject_put() to fix this issue. Previous
commit "b8eb718348b8" fixed a similar problem.

Fixes: 7b96953bc640 ("vfio: Mediated device Core driver")
Signed-off-by: Qiushi Wu <wu000273@umn.edu>
Reviewed-by: Cornelia Huck <cohuck@redhat.com>
Reviewed-by: Kirti Wankhede <kwankhede@nvidia.com>
Signed-off-by: Alex Williamson <alex.williamson@redhat.com>

Here is the root cause:
The bug is caused by the failure to properly manage the reference count of a kobject when the `kobject_init_and_add()` function returns an error. The original code incorrectly used `kfree()` to free the memory allocated for the type, which does not account for the reference taken by `kobject_init_and_add()`. This leads to a memory leak since the kobject is not properly released when an error occurs.

Here is the patch:

 static struct mdev_type *add_mdev_supported_type(struct mdev_parent *parent,
 						 struct attribute_group *group)
 {
 	struct mdev_type *type;
 	int ret;

 	if (!group->name) {
 		pr_err("%s: Type name empty!\n", __func__);
 		return ERR_PTR(-EINVAL);
 	}

 	type = kzalloc(sizeof(*type), GFP_KERNEL);
 	if (!type)
 		return ERR_PTR(-ENOMEM);

 	type->kobj.kset = parent->mdev_types_kset;

 	ret = kobject_init_and_add(&type->kobj, &mdev_type_ktype, NULL,
 				   "%s-%s", dev_driver_string(parent->dev),
 				   group->name);
 	if (ret) {
-		kfree(type);
+		kobject_put(&type->kobj);
 		return ERR_PTR(ret);
 	}

 	ret = sysfs_create_file(&type->kobj, &mdev_type_attr_create.attr);
 	if (ret)
 		goto attr_create_failed;

 	type->devices_kobj = kobject_create_and_add("devices", &type->kobj);
 	if (!type->devices_kobj) {
 		ret = -ENOMEM;
 		goto attr_devices_failed;
 	}

 	ret = sysfs_create_files(&type->kobj,
 				 (const struct attribute **)group->attrs);
 	if (ret) {
 		ret = -ENOMEM;
 		goto attrs_failed;
 	}

 	type->group = group;
 	type->parent = parent;
 	return type;

 attrs_failed:
 	kobject_put(type->devices_kobj);
 attr_devices_failed:
 	sysfs_remove_file(&type->kobj, &mdev_type_attr_create.attr);
 attr_create_failed:
 	kobject_del(&type->kobj);
 	kobject_put(&type->kobj);
 	return ERR_PTR(ret);
 }



